package com.example

import com.example.ExamQuestionHelper.QSpec
import com.example.ExamQuestionHelper.buildPoolFromShortAnswers
import com.example.ExamQuestionHelper.buildPoolFromSubjectMaster
import com.example.ExamQuestionHelper.dedupPool
import com.example.ExamQuestionHelper.quizQuestionToSpec
import com.example.ExamQuestionHelper.selectFromMasterPool

/**
 * Curated Sri Lankan & World History Question Pool (Grades 10 & 11 O/L).
 * Combines QuizBankHistory (100), curated Kings/Reforms/Chronology/World History MCQs (180+),
 * SubjectMasterHistory (1,580+ multi-angle), and ShortAnswer History (400 G10+G11).
 */
object HistoryMockPoolHelper {

  private val pool: List<QSpec> by lazy { buildMasterPool() }

  fun getQuestion(grade: String, term: Int, paperIdx: Int, qNum: Int): MockExamQuestion {
    return selectFromMasterPool(pool, grade, term, paperIdx, qNum)
  }

  private fun buildMasterPool(): List<QSpec> {
    val raw = ArrayList<QSpec>(2600)

    // 1. 100 Curated QuizBankHistory MCQs
    for (setIdx in 1..10) {
      for (qIdx in 1..10) {
        val qq = QuizBankHistory.getQuestion("10", setIdx, qIdx, qIdx, "ඉතිහාසය")
        raw.add(quizQuestionToSpec("ඉතිහාසය - ඒකකය $setIdx", qq))
      }
    }

    // 2. Curated Sri Lankan & World History Chronology, Rulers, Constitutions & Reforms MCQs
    raw.addAll(buildCuratedHistoryFacts())

    // 3. SubjectMasterRepository History multi-angle pool (~1,580 specs)
    raw.addAll(
      buildPoolFromSubjectMaster(
        categories = SubjectMasterRepository.getCategoriesForSubject("ඉතිහාසය"),
        subjectLabel = "ඉතිහාසය",
        seedBase = 41
      )
    )

    // 4. ShortAnswerMasterRepository Grade 10 & Grade 11 History (~400 specs)
    raw.addAll(buildPoolFromShortAnswers("ඉතිහාසය"))

    return dedupPool(raw)
  }

  private fun buildCuratedHistoryFacts(): List<QSpec> {
    val list = ArrayList<QSpec>(220)

    // A. Ancient & Medieval Kings / Capital Shifting / Irrigation - 40 MCQs
    val sriLankaHistory = listOf(
      QuadH("අනුරාධපුර රාජධානිය විධිමත් අගනගරයක් ලෙස සැලසුම් කළ පළමු පාලකයා කවුද?", "පණ්ඩුකාභය රජු", listOf("මුටසීව රජු", "දේවානම්පියතිස්ස රජු", "විජය කුමරු"), "ක්‍රි.පූ. 4 වන සියවසේ පණ්ඩුකාභය රජතුමා අභය වැව (බසවක්කුලම) හා නගර පරිපාලනය ඇරඹීය."),
      QuadH("දේවානම්පියතිස්ස රජු දවස ලක්දිවට බුදුදහම ගෙන ආ මිහිඳු මහරහතන් වහන්සේ වැඩම කළ පුණ්‍ය දිනය කුමක්ද?", "පොසොන් පුන් පොහෝ දින", listOf("වෙසක් පුන් පොහෝ දින", "ඇසළ පුන් පොහෝ දින", "මැදින් පුන් පොහෝ දින"), "මිහින්තලේදී පොසොන් පොහෝ දින මහින්දාගමනය සිදුවිය."),
      QuadH("ශ්‍රී ලංකාව පළමුවරට එක්සේසත් කොට රුවන්වැලිසෑය හා ලෝවාමහාපාය ඉදිකළ වීර නරපතියා කවුද?", "දුටුගැමුණු රජතුමා", listOf("කාවන්තිස්ස රජු", "සද්ධාතිස්ස රජු", "වළගම්බා රජු"), "දුටුගැමුණු රජු විසින් රුවන්වැලිසෑය, මිරිසවැටිය හා ලෝවාමහාපාය කරවන ලදී."),
      QuadH("වළගම්බා රජ සමයේදී ත්‍රිපිටකය ප්‍රථම වරට ග්‍රන්ථාරූඪ කරනු ලැබුවේ කුමන ස්ථානයේදීද?", "මාතලේ අලුවිහාරයේදී", listOf("මිහින්තලේදී", "අනුරාධපුර මහාවිහාරයේදී", "තිස්සමහාරාමයේදී"), "බැමිණිතියා සාය සහ විදේශ ආක්‍රමණ මැද ධර්මය රැකගැනීමට අලුවිහාරයේදී ග්‍රන්ථාරූඪ කෙරිණි."),
      QuadH("මහා වැව් සංස්කෘතිය ආරම්භ කරමින් වැව් 11 ක් සහ ඇළවල් 12 ක් ඉදිකළ ලංකාවේ පළමු මහා වැව් නිර්මාතෘවරයා කවුද?", "වසභ රජතුමා", listOf("මහසෙන් රජු", "ධාතුසේන රජු", "මහා පරාක්‍රමබාහු"), "ලම්බකර්ණ වංශයේ ආරම්භක වසභ රජු (ක්‍රි.ව. 67-111) මහා පරිමාණ වාරි කර්මාන්ත ඇරඹීය."),
      QuadH("මින්නේරිය වැව ඇතුළු වැව් 16 ක් ඉදිකර 'මින්නේරි දෙවියන්' ලෙස ජනතා ගෞරවයට පාත්‍ර වූ රජු කවුද?", "මහසෙන් රජතුමා", listOf("වසභ රජු", "ධාතුසේන රජු", "අග්බෝ I රජු"), "මහසෙන් රජු මින්නේරිය, කවුඩුල්ල, හුරුළුවැව ආදිය කරවීය."),
      QuadH("කලා වැව ඉදිකර ජය ගඟ (යෝධ ඇළ) මගින් තිසා වැවට ජලය ගෙන ගිය අනුරාධපුර රජතුමා කවුද?", "ධාතුසේන රජතුමා", listOf("කාශ්‍යප රජු", "මුගලන් රජු", "පළමුවන විජයබාහු"), "සැතපුමට අඟලක් බැස්ම ඇති යෝධ ඇළ ධාතුසේන රජුගේ විශිෂ්ට වාරි නිර්මාණයකි."),
