    // C. Reverse Questions from Kings/Events to enrich pool (~60)
    val dynastiesAndSites = listOf(
      Triple("ගල් විහාරයේ හිටි, හිඳි හා පිරිනිවන් පිළිම නෙළනු ලැබූ යුගය", "පොළොන්නරු යුගය", listOf("අනුරාධපුර යුගය", "දඹදෙණි යුගය", "මහනුවර යුගය")),
      Triple("රුවන්වැලි මහා සෑය, අභයගිරිය හා ජේතවනාරාමය අයත් වන යුගය", "අනුරාධපුර යුගය", listOf("පොළොන්නරු යුගය", "කෝට්ටේ යුගය", "මහනුවර යුගය")),
      Triple("ඇම්බැක්කේ දේවාලයේ විශිෂ්ට ලී කැටයම් හා දළදා මාලිගාවේ පත්තිරිප්පුව අයත් යුගය", "මහනුවර / ගම්පොළ සම්ප්‍රදාය (ප්‍රධානව මහනුවර යුගය)", listOf("පොළොන්නරු යුගය", "සීතාවක යුගය", "රයිගම යුගය")),
      Triple("ගඩලාදෙණිය හා ලංකාතිලක විහාර නිර්මාණය කරන ලද්දේ කුමන යුගයේදීද?", "ගම්පොළ යුගය (හතරවන බුවනෙකබාහු සමයේ)", listOf("අනුරාධපුර යුගය", "සීතාවක යුගය", "රෝහණ යුගය")),
      Triple("මහාවංසයේ දෙවන කොටස හෙවත් චූලවංසය ආරම්භ කරන ලද්දේ කුමන යතිවරයාණන් විසින්ද?", "ධම්මකිත්ති හිමියන් (පොළොන්නරු සමයේ)", listOf("මහානාම හිමියන්", "බුද්ධඝෝෂ හිමියන්", "ශ්‍රී රාහුල හිමියන්")),
      Triple("කෝට්ටේ සාහිත්‍ය යුගයේ 'පරෙවි', 'සැළලිහිණි' ආදී සන්දේශ කාව්‍ය බිහිවූයේ කුමන රජුගේ රාජ්‍ය සමයේද?", "හයවන පරාක්‍රමබාහු රජුගේ සමයේ", listOf("පළමුවන විජයබාහු", "පළමුවන රාජසිංහ", "දෙවන පරාක්‍රමබාහු")),
      Triple("ඉංග්‍රීසි යුගයේ වෙල්ලස්සේ කැරැල්ල මැඩපැවැත්වීමෙන් පසු ඉංග්‍රීසීන් විසින් 1818 නොවැම්බර් 21 දින නිකුත් කළ ප්‍රකාශනය", "1818 රාජ්‍ය ප්‍රකාශනය (Proclamation of 1818)", listOf("1815 උඩරට ගිවිසුම", "1833 කෝල්බෲක් නියෝගය", "1947 නිදහස් පනත")),
      Triple("පෘතුගීසි පාලනය යටතේ ශ්‍රී ලංකාවේ මුහුදුබඩ පළාත්වල ඉඩම් බදු හා ආදායම් වාර්තා කර තැබූ ලේඛන", "තෝම්බු (Thombo)", listOf("සන්නස්", "තඹ පත්", "සෙල්ලිපි")),
      Triple("ලන්දේසි පාලන සමයේ රෝමානු-ලන්දේසි නීතිය (Roman-Dutch Law) මෙරටට හඳුන්වා දුන් අතර ඔවුන් පිහිටුවූ උසස් අධිකරණය", "රාඩ් වැන් ජස්ටීසි (Raad van Justitie)", listOf("ශ්‍රේෂ්ඨාධිකරණය", "රාජසභාව", "ගම්සභාව")),
      Triple("ලොව ප්‍රථම මහජන එක්සත් ජාතීන්ගේ සංවිධානය (UNO) දෙවන ලෝක යුද්ධයෙන් පසු ආරම්භ කළ දිනය", "1945 ඔක්තෝබර් 24", listOf("1919 ජුනි 28", "1939 සැප්තැම්බර් 01", "1948 දෙසැම්බර් 10"))
    )
    for ((prompt, ans, wr) in dynastiesAndSites) {
      list.add(QSpec("ශ්‍රී ලංකා සංස්කෘතික හා රාජ්‍ය උරුමය", "$prompt කුමක්ද?", ans, wr, "මෙය O/L ඉතිහාසය විෂය නිර්දේශයේ ප්‍රධාන පරීක්ෂණ කරුණකි — $ans."))
    }

    return list
  }

  private data class QuadH(val q: String, val a: String, val wrongs: List<String>, val exp: String)
}
